23	
24	extern "C" __global__ __aicore__ void ai_infra_aggregate_hidden(
25	    GM_ADDR input, GM_ADDR weight, GM_ADDR mask, GM_ADDR output, GM_ADDR workspace, GM_ADDR tiling)
