31	        const AiInfraAggregateHiddenTilingData *__restrict tilingData = &tiling_data_in;
32	        KernelAiInfraAggregateHidden<bfloat16_t> op(&pipe, tilingData);
33	        op.Init(input, weight, mask, output);
34	        op.Process();
35	    } else if (TILING_KEY_IS(AGGREGATE_HIDDEN_HALF)) {
