10	
11	/*!
12	 * \file ai_infra_aggregate_hidden.h
13	 * \brief
14	 */
15	#ifndef _AGGREGATE_HIDDEN_H_
16	#define _AGGREGATE_HIDDEN_H_
17	#include "kernel_operator.h"
18	#include "ai_infra_aggregate_hidden_common.h"
19	
20	namespace AiInfraAggregateHidden {
21	using namespace AscendC;
22	
23	template <typename DTYPE>
24	class KernelAiInfraAggregateHidden : public KernelAiInfraAggregateHiddenCutHBS<DTYPE> {
25	public:
26	    __aicore__ inline KernelAiInfraAggregateHidden(TPipe *pipe, const AiInfraAggregateHiddenTilingData *tiling)
27	        : KernelAiInfraAggregateHiddenCutHBS<DTYPE>(pipe, tiling)
28	    {}
29	
30	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR weight, GM_ADDR mask, GM_ADDR output)
31	    {
32	        this->InitSharedData();
33	        this->inputGm.SetGlobalBuffer((__gm__ DTYPE *)input);    //  [sSize, bSize, hSize]
34	        this->weightGm.SetGlobalBuffer((__gm__ DTYPE *)weight);  //  [3, hSize]
35	        if (this->tilingData_->ifMask) {
36	            this->maskGm.SetGlobalBuffer((__gm__ bool *)mask);  //  [bSize, sSize]
37	        }
38	        this->outputGm.SetGlobalBuffer((__gm__ DTYPE *)output);  //  [sSize, bSize, hSize]
39	
40	        // max alignBaseH = 4096 -> 4K
41	        this->pipe_->InitBuffer(
42	            this->inQueueX, NUM_TWO, this->alignBaseH * sizeof(DTYPE));       // 2 * alignBaseH * 2 / 1024 = 16K
43	        this->pipe_->InitBuffer(this->y2, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
44	        this->pipe_->InitBuffer(this->y1, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
45	        this->pipe_->InitBuffer(this->y0, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
46	        this->pipe_->InitBuffer(this->inQueueW,
47	            NUM_TWO,
48	            NUM_THREE * this->alignBaseH * sizeof(float));  // 2 * 3 * alignBaseH * 4 / 1024 = 96K
49	        this->pipe_->InitBuffer(this->inputFp32, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
50	        this->pipe_->InitBuffer(
51	            this->outQueue, NUM_TWO, this->alignBaseH * sizeof(DTYPE));  //  2 * alignBaseH * 2 / 1024 = 16K
52	    }
53	
54	    __aicore__ inline void Process()
55	    {
56	        // CopyIn weight
57	        LocalTensor<float> weightFp32 = this->inQueueW.template AllocTensor<float>();
58	        LocalTensor<DTYPE> localW0 = weightFp32.template ReinterpretCast<DTYPE>()[this->alignBaseH];
59	        LocalTensor<DTYPE> localW1 = localW0[this->alignBaseH * NUM_TWO];
60	        LocalTensor<DTYPE> localW2 = localW1[this->alignBaseH * NUM_TWO];
61	        DataCopyPadExtParams<DTYPE> padParams{false, 0, 0, 0};
62	        DataCopyExtParams copyParamsContinguous;
63	        copyParamsContinguous.blockCount = NUM_THREE;  // weight [3, hSize]
64	        copyParamsContinguous.blockLen = this->baseH * sizeof(DTYPE);
65	        copyParamsContinguous.srcStride = (this->tilingData_->hSize - this->baseH) * sizeof(DTYPE);
66	        copyParamsContinguous.dstStride = this->alignBaseH * sizeof(DTYPE) / BLOCK_SIZE;
67	        int64_t gmOffset = this->tilingData_->baseH *
68	                           this->baseHIdx;  // this->baseH 可能更改为尾块大小了 所以这里要用this->tilingData->baseH
69	        DataCopyPad(localW0, this->weightGm[gmOffset], copyParamsContinguous, padParams);
70	        this->inQueueW.EnQue(weightFp32);
71	        weightFp32 = this->inQueueW.template DeQue<float>();
72	        localW0 = weightFp32.template ReinterpretCast<DTYPE>()[this->alignBaseH];
73	        localW1 = localW0[this->alignBaseH * NUM_TWO];
74	        localW2 = localW1[this->alignBaseH * NUM_TWO];
75	        LocalTensor<float> localW0FP32 = weightFp32;
76	        LocalTensor<float> localW1FP32 = weightFp32[this->alignBaseH];
77	        LocalTensor<float> localW2FP32 = weightFp32[this->alignBaseH * NUM_TWO];
78	        Cast(localW0FP32, localW0, RoundMode::CAST_NONE, this->alignBaseH);
79	        Cast(localW1FP32, localW1, RoundMode::CAST_NONE, this->alignBaseH);
80	        Cast(localW2FP32, localW2, RoundMode::CAST_NONE, this->alignBaseH);
81	        this->inQueueW.EnQue(weightFp32);
82	        weightFp32 = this->inQueueW.template DeQue<float>();
83	
84	        LocalTensor<float> y0Fp32 = this->y0.template Get<float>();
85	        LocalTensor<float> y1Fp32 = this->y1.template Get<float>();
86	        LocalTensor<float> y2Fp32 = this->y2.template Get<float>();
87	        for (int64_t bIdx = 0; bIdx < this->baseB; ++bIdx) {
88	            InitY<DTYPE>(y0Fp32, y1Fp32, weightFp32, bIdx);
89	            for (int64_t sIdx = 0; sIdx < this->baseS; ++sIdx) {
90	                LocalTensor<DTYPE> xLocal = this->inQueueX.template AllocTensor<DTYPE>();
91	                CopyIn<DTYPE>(xLocal, bIdx, sIdx);
92	                this->inQueueX.EnQue(xLocal);
93	                xLocal = this->inQueueX.template DeQue<DTYPE>();
94	                LocalTensor<float> xLocalFp32 = this->inputFp32.template Get<float>();
95	                Cast(xLocalFp32, xLocal, RoundMode::CAST_NONE, this->alignBaseH);
96	                this->inQueueX.FreeTensor(xLocal);
97	                Compute<DTYPE>(xLocalFp32, weightFp32, y0Fp32, y1Fp32, y2Fp32, bIdx, sIdx);
98	                CopyOut<DTYPE>(y2Fp32, this->outputGm, bIdx, sIdx);
99	            }
100	        }
101	        this->inQueueW.FreeTensor(weightFp32);
102	    }
103	
104	    template <typename T>
105	    __aicore__ inline void InitY(const LocalTensor<float> &y0Fp32, const LocalTensor<float> &y1Fp32,
106	        const LocalTensor<float> &weightFp32, int64_t bIdx)
107	    {
108	        if (this->baseSIdx == NUM_ZERO) {
109	            Duplicate(y0Fp32, static_cast<float>(0.0f), this->alignBaseH);
110	            Duplicate(y1Fp32, static_cast<float>(0.0f), this->alignBaseH);
111	            PipeBarrier<PIPE_V>();
112	        } else {
113	            // CopyIn input[sSize-2]
114	            int64_t startSIdx = this->tilingData_->baseS * this->baseSIdx;
115	            int64_t preSIdx = startSIdx - NUM_TWO;
116	            int64_t startBIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
117	            int64_t gmOffset4Y0 = preSIdx * this->tilingData_->bSize * this->tilingData_->hSize +
118	                                  startBIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
119	            int64_t gmOffset4Y1 = (preSIdx + NUM_ONE) * this->tilingData_->bSize * this->tilingData_->hSize +
120	                                  startBIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
121	            LocalTensor<T> xLocal = this->inQueueX.template AllocTensor<T>();
122	            LocalTensor<float> xLocalFp32 = this->inputFp32.template Get<float>();
123	            DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
124	            DataCopyExtParams copyParamsContinguous;
125	            copyParamsContinguous.blockCount = NUM_ONE;  // input [sSize, bSize, hSize]
126	            copyParamsContinguous.blockLen = this->baseH * sizeof(T);
127	            copyParamsContinguous.srcStride = 0;
128	            copyParamsContinguous.dstStride = 0;
129	            if (gmOffset4Y0 < NUM_ZERO) {
130	                Duplicate(xLocalFp32, static_cast<float>(0.0f), this->alignBaseH);
131	                PipeBarrier<PIPE_V>();
132	            } else {
133	                DataCopyPad(xLocal, this->inputGm[gmOffset4Y0], copyParamsContinguous, padParams);
134	                this->inQueueX.EnQue(xLocal);
135	                xLocal = this->inQueueX.template DeQue<DTYPE>();
136	                Cast(xLocalFp32, xLocal, RoundMode::CAST_NONE, this->alignBaseH);
137	                PipeBarrier<PIPE_V>();
138	                this->inQueueX.FreeTensor(xLocal);
139	            }
140	            // Calc y0 = input[sSize-2] * w0
141	            Mul(y0Fp32, xLocalFp32, weightFp32, this->alignBaseH);
142	            PipeBarrier<PIPE_V>();
143	            xLocal = this->inQueueX.template AllocTensor<T>();
144	            // CopyIn input[sSize-1]
145	            DataCopyPad(xLocal, this->inputGm[gmOffset4Y1], copyParamsContinguous, padParams);
146	            this->inQueueX.EnQue(xLocal);
147	            xLocal = this->inQueueX.template DeQue<DTYPE>();
148	            Cast(xLocalFp32, xLocal, RoundMode::CAST_NONE, this->alignBaseH);
149	            PipeBarrier<PIPE_V>();
150	            this->inQueueX.FreeTensor(xLocal);
151	            // Calc y1 = y0 + input[sSize-1] * w1
152	            Mul(y1Fp32, xLocalFp32, weightFp32[this->alignBaseH], this->alignBaseH);
153	            PipeBarrier<PIPE_V>();
154	            Add(y1Fp32, y0Fp32, y1Fp32, this->alignBaseH);
155	            PipeBarrier<PIPE_V>();
156	            // Update y0 = input[sSize-1] * w0
157	            Mul(y0Fp32, xLocalFp32, weightFp32, this->alignBaseH);
158	            PipeBarrier<PIPE_V>();
159	        }
160	    }
161	
162	    template <typename T>
163	    __aicore__ inline void CopyIn(const LocalTensor<T> &xLocal, int64_t bIdx, int64_t sIdx)
164	    {
165	        int64_t batchIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
166	        int64_t seqIdx = this->tilingData_->baseS * this->baseSIdx + sIdx;
167	        int64_t gmOffset = seqIdx * this->tilingData_->bSize * this->tilingData_->hSize +
168	                           batchIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
169	        // CopyIn input[s,b]
170	        DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
171	        DataCopyExtParams copyParamsContinguous;
172	        copyParamsContinguous.blockCount = NUM_ONE;  // input [sSize, bSize, hSize]
173	        copyParamsContinguous.blockLen = this->baseH * sizeof(T);
174	        copyParamsContinguous.srcStride = 0;
175	        copyParamsContinguous.dstStride = 0;
176	        DataCopyPad(xLocal, this->inputGm[gmOffset], copyParamsContinguous, padParams);
177	    }
178	
179	    template <typename T>
180	    __aicore__ inline void Compute(const LocalTensor<float> &xLocalFp32, const LocalTensor<float> &weightFp32,
181	        const LocalTensor<float> &y0Fp32, const LocalTensor<float> &y1Fp32, const LocalTensor<float> &y2Fp32,
182	        int64_t bIdx, int64_t sIdx)
183	    {
184	        LocalTensor<float> localW0FP32 = weightFp32;
185	        LocalTensor<float> localW1FP32 = weightFp32[this->alignBaseH];
186	        LocalTensor<float> localW2FP32 = weightFp32[this->alignBaseH * NUM_TWO];
187	        // Cacl y2 = (y1 + x * w2) * mask[b, s]
188	        PipeBarrier<PIPE_V>();
189	        if (this->tilingData_->ifMask) {
190	            int64_t batchIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
191	            int64_t seqIdx = this->tilingData_->baseS * this->baseSIdx + sIdx;
192	            int64_t tokenIdx = batchIdx * this->tilingData_->sSize + seqIdx;
193	            bool maskValue = this->maskGm(tokenIdx);
194	            SetWaitFlag<HardEvent::S_V>(HardEvent::S_V);
195	            if (maskValue) {
196	                Mul(y2Fp32, xLocalFp32, localW2FP32, this->alignBaseH);
197	                PipeBarrier<PIPE_V>();
198	                Add(y2Fp32, y2Fp32, y1Fp32, this->alignBaseH);
199	                PipeBarrier<PIPE_V>();
200	            } else {
201	                Duplicate(y2Fp32, static_cast<float>(0.0f), this->alignBaseH);
202	                PipeBarrier<PIPE_V>();
203	            }
204	        } else {
205	            Mul(y2Fp32, xLocalFp32, localW2FP32, this->alignBaseH);
206	            PipeBarrier<PIPE_V>();
207	            Add(y2Fp32, y2Fp32, y1Fp32, this->alignBaseH);
208	            PipeBarrier<PIPE_V>();
209	        }
210	        // Update y1, y0
211	        Mul(y1Fp32, xLocalFp32, localW1FP32, this->alignBaseH);
212	        PipeBarrier<PIPE_V>();
213	        Add(y1Fp32, y1Fp32, y0Fp32, this->alignBaseH);
214	        PipeBarrier<PIPE_V>();
215	        Mul(y0Fp32, xLocalFp32, localW0FP32, this->alignBaseH);
216	        PipeBarrier<PIPE_V>();
217	    }
218	
219	    template <typename T>
220	    __aicore__ inline void CopyOut(
221	        const LocalTensor<float> &y2Fp32, const GlobalTensor<T> &dstNd, int64_t bIdx, int64_t sIdx)
222	    {
223	        LocalTensor<T> outLocal = this->outQueue.template AllocTensor<T>();
224	        if constexpr (std::is_same<T, bfloat16_t>::value) {
225	            Cast(outLocal, y2Fp32, RoundMode::CAST_RINT, this->alignBaseH);
226	        } else if constexpr (std::is_same<T, half>::value) {
227	            Cast(outLocal, y2Fp32, RoundMode::CAST_NONE, this->alignBaseH);
228	        }
229	        this->outQueue.EnQue(outLocal);
230	        outLocal = this->outQueue.template DeQue<T>();
231	        // Copyout output [S, B, H]
232	        int64_t seqIdx = this->tilingData_->baseS * this->baseSIdx + sIdx;
233	        int64_t batchIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
234	        int64_t gmOffset = seqIdx * this->tilingData_->bSize * this->tilingData_->hSize +
235	                           batchIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
236	        DataCopyExtParams copyParamsContinguous;
237	        copyParamsContinguous.blockCount = NUM_ONE;
238	        copyParamsContinguous.blockLen = this->baseH * sizeof(T);
239	        copyParamsContinguous.srcStride = 0;
240	        copyParamsContinguous.dstStride = 0;
241	        DataCopyPad(dstNd[gmOffset], outLocal, copyParamsContinguous);
242	        this->outQueue.FreeTensor(outLocal);
243	    }
244	
245	private:
246	};
247	}  // namespace AiInfraAggregateHidden
248	
249	#endif  // _AGGREGATE_HIDDEN_H_

