/*!
 * \file ai_infra_aggregate_hidden.h
 * \brief
 */
#ifndef _AGGREGATE_HIDDEN_H_
#define _AGGREGATE_HIDDEN_H_
#include "kernel_operator.h"
#include "ai_infra_aggregate_hidden_common.h"

namespace AiInfraAggregateHidden {
using namespace AscendC;

template <typename DTYPE>
class KernelAiInfraAggregateHidden : public KernelAiInfraAggregateHiddenCutHBS<DTYPE> {
public:
    __aicore__ inline KernelAiInfraAggregateHidden(TPipe *pipe, const AiInfraAggregateHiddenTilingData *tiling)
        : KernelAiInfraAggregateHiddenCutHBS<DTYPE>(pipe, tiling)
    {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR weight, GM_ADDR mask, GM_ADDR output)
    {
        this->InitSharedData();
        this->inputGm.SetGlobalBuffer((__gm__ DTYPE *)input);    //  [sSize, bSize, hSize]
        this->weightGm.SetGlobalBuffer((__gm__ DTYPE *)weight);  //  [3, hSize]
        if (this->tilingData_->ifMask) {
            this->maskGm.SetGlobalBuffer((__gm__ bool *)mask);  //  [bSize, sSize]
        }
        this->outputGm.SetGlobalBuffer((__gm__ DTYPE *)output);  //  [sSize, bSize, hSize]

        // max alignBaseH = 4096 -> 4K
        this->pipe_->InitBuffer(
            this->inQueueX, NUM_TWO, this->alignBaseH * sizeof(DTYPE));       // 2 * alignBaseH * 2 / 1024 = 16K
        this->pipe_->InitBuffer(this->y2, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
        this->pipe_->InitBuffer(this->y1, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
        this->pipe_->InitBuffer(this->y0, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
        this->pipe_->InitBuffer(this->inQueueW,
            NUM_TWO,
            NUM_THREE * this->alignBaseH * sizeof(float));  // 2 * 3 * alignBaseH * 4 / 1024 = 96K
        this->pipe_->InitBuffer(this->inputFp32, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
        this->pipe_->InitBuffer(
            this->outQueue, NUM_TWO, this->alignBaseH * sizeof(DTYPE));  //  2 * alignBaseH * 2 / 1024 = 16K
    }

    __aicore__ inline void Process()
    {
        // CopyIn weight
        LocalTensor<float> weightFp32 = this->inQueueW.template AllocTensor<float>();
        LocalTensor<DTYPE> localW0 = weightFp32.template ReinterpretCast<DTYPE>()[this->alignBaseH];
        LocalTensor<DTYPE> localW1 = localW0[this->alignBaseH * NUM_TWO];
        LocalTensor<DTYPE> localW2 = localW1[this->alignBaseH * NUM_TWO];
        DataCopyPadExtParams<DTYPE> padParams{false, 0, 0, 0};
        DataCopyExtParams copyParamsContinguous;
        copyParamsContinguous.blockCount = NUM_THREE;  // weight [3, hSize]
        copyParamsContinguous.blockLen = this->baseH * sizeof(DTYPE);
        copyParamsContinguous.srcStride = (this->tilingData_->hSize - this->baseH) * sizeof(DTYPE);
        copyParamsContinguous.dstStride = this->alignBaseH * sizeof(DTYPE) / BLOCK_SIZE;
        int64_t gmOffset = this->tilingData_->baseH *
                           this->baseHIdx;  // this->baseH 可能更改为尾块大小了 所以这里要用this->tilingData->baseH
        DataCopyPad(localW0, this->weightGm[gmOffset], copyParamsContinguous, padParams);
        this->inQueueW.EnQue(weightFp32);
        weightFp32 = this->inQueueW.template DeQue<float>();
        localW0 = weightFp32.template ReinterpretCast<DTYPE>()[this->alignBaseH];
        localW1 = localW0[this->alignBaseH * NUM_TWO];
        localW2 = localW1[this->alignBaseH * NUM_TWO];
        LocalTensor<float> localW0FP32 = weightFp32;
        LocalTensor<float> localW1FP32 = weightFp32[this->alignBaseH];
        LocalTensor<float> localW2FP32 = weightFp32[this->alignBaseH * NUM_TWO];
        Cast(localW0FP32, localW0, RoundMode::CAST_NONE, this->alignBaseH);
        Cast(localW1FP32, localW1, RoundMode::CAST_NONE, this->alignBaseH);
        Cast(localW2FP32, localW2, RoundMode::CAST_NONE, this->alignBaseH);
        this->inQueueW.EnQue(weightFp32);
        weightFp32 = this->inQueueW.template DeQue<float>();

        LocalTensor<float> y0Fp32 = this->y0.template Get<float>();
        LocalTensor<float> y1Fp32 = this->y1.template Get<float>();
        LocalTensor<float> y2Fp32 = this->y2.template Get<float>();
        for (int64_t bIdx = 0; bIdx < this->baseB; ++bIdx) {
            InitY<DTYPE>(y0Fp32, y1Fp32, weightFp32, bIdx);
            for (int64_t sIdx = 0; sIdx < this->baseS; ++sIdx) {
                LocalTensor<DTYPE> xLocal = this->inQueueX.template AllocTensor<DTYPE>();
                CopyIn<DTYPE>(xLocal, bIdx, sIdx);
                this->inQueueX.EnQue(xLocal);
                xLocal = this->inQueueX.template DeQue<DTYPE>();
                LocalTensor<float> xLocalFp32 = this->inputFp32.template Get<float>();
                Cast(xLocalFp32, xLocal, RoundMode::CAST_NONE, this->alignBaseH);
                this->inQueueX.FreeTensor(xLocal);
                Compute<DTYPE>(xLocalFp32, weightFp32, y0Fp32, y1Fp32, y2Fp32, bIdx, sIdx);
                CopyOut<DTYPE>(y2Fp32, this->outputGm, bIdx, sIdx);
            }
        }
        this->inQueueW.FreeTensor(weightFp32);
    }

    template <typename T>
    __aicore__ inline void InitY(const LocalTensor<float> &y0Fp32, const LocalTensor<float> &y1Fp32,
        const LocalTensor<float> &weightFp32, int64_t bIdx)
    {
        if (this->baseSIdx == NUM_ZERO) {
            Duplicate(y0Fp32, static_cast<float>(0.0f), this->alignBaseH);
            Duplicate(y1Fp32, static_cast<float>(0.0f), this->alignBaseH);
            PipeBarrier<PIPE_V>();
        } else {
            // CopyIn input[sSize-2]
            int64_t startSIdx = this->tilingData_->baseS * this->baseSIdx;
            int64_t preSIdx = startSIdx - NUM_TWO;
            int64_t startBIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
            int64_t gmOffset4Y0 = preSIdx * this->tilingData_->bSize * this->tilingData_->hSize +
                                  startBIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
            int64_t gmOffset4Y1 = (preSIdx + NUM_ONE) * this->tilingData_->bSize * this->tilingData_->hSize +
                                  startBIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
            LocalTensor<T> xLocal = this->inQueueX.template AllocTensor<T>();
            LocalTensor<float> xLocalFp32 = this->inputFp32.template Get<float>();
            DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
            DataCopyExtParams copyParamsContinguous;
            copyParamsContinguous.blockCount = NUM_ONE;  // input [sSize, bSize, hSize]
            copyParamsContinguous.blockLen = this->baseH * sizeof(T);
            copyParamsContinguous.srcStride = 0;
            copyParamsContinguous.dstStride = 0;
            if (gmOffset4Y0 < NUM_ZERO) {
                Duplicate(xLocalFp32, static_cast<float>(0.0f), this->alignBaseH);
                PipeBarrier<PIPE_V>();
            } else {
                DataCopyPad(xLocal, this->inputGm[gmOffset4Y0], copyParamsContinguous, padParams);
                this->inQueueX.EnQue(xLocal);
                xLocal = this->inQueueX.template DeQue<DTYPE>();
                Cast(xLocalFp32, xLocal, RoundMode::CAST_NONE, this->alignBaseH);
                PipeBarrier<PIPE_V>();
                this->inQueueX.FreeTensor(xLocal);
            }
            // Calc y0 = input[sSize-2] * w0
            Mul(y0Fp32, xLocalFp32, weightFp32, this->alignBaseH);
            PipeBarrier<PIPE_V>();
            xLocal = this->inQueueX.template AllocTensor<T>();
            // CopyIn input[sSize-1]
            DataCopyPad(xLocal, this->inputGm[gmOffset4Y1], copyParamsContinguous, padParams);
            this->inQueueX.EnQue(xLocal);
            xLocal = this->inQueueX.template DeQue<DTYPE>();
            Cast(xLocalFp32, xLocal, RoundMode::CAST_NONE, this->alignBaseH);
            PipeBarrier<PIPE_V>();
            this->inQueueX.FreeTensor(xLocal);
            // Calc y1 = y0 + input[sSize-1] * w1
            Mul(y1Fp32, xLocalFp32, weightFp32[this->alignBaseH], this->alignBaseH);
            PipeBarrier<PIPE_V>();
            Add(y1Fp32, y0Fp32, y1Fp32, this->alignBaseH);
            PipeBarrier<PIPE_V>();
            // Update y0 = input[sSize-1] * w0
            Mul(y0Fp32, xLocalFp32, weightFp32, this->alignBaseH);
            PipeBarrier<PIPE_V>();
        }
    }

    template <typename T>
    __aicore__ inline void CopyIn(const LocalTensor<T> &xLocal, int64_t bIdx, int64_t sIdx)
    {
        int64_t batchIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
        int64_t seqIdx = this->tilingData_->baseS * this->baseSIdx + sIdx;
        int64_t gmOffset = seqIdx * this->tilingData_->bSize * this->tilingData_->hSize +
                           batchIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
        // CopyIn input[s,b]
        DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        DataCopyExtParams copyParamsContinguous;
        copyParamsContinguous.blockCount = NUM_ONE;  // input [sSize, bSize, hSize]
        copyParamsContinguous.blockLen = this->baseH * sizeof(T);
        copyParamsContinguous.srcStride = 0;
        copyParamsContinguous.dstStride = 0;
        DataCopyPad(xLocal, this->inputGm[gmOffset], copyParamsContinguous, padParams);
    }

    template <typename T>
    __aicore__ inline void Compute(const LocalTensor<float> &xLocalFp32, const LocalTensor<float> &weightFp32,
        const LocalTensor<float> &y0Fp32, const LocalTensor<float> &y1Fp32, const LocalTensor<float> &y2Fp32,
        int64_t bIdx, int64_t sIdx)
    {
        LocalTensor<float> localW0FP32 = weightFp32;
        LocalTensor<float> localW1FP32 = weightFp32[this->alignBaseH];
        LocalTensor<float> localW2FP32 = weightFp32[this->alignBaseH * NUM_TWO];
        // Cacl y2 = (y1 + x * w2) * mask[b, s]
        PipeBarrier<PIPE_V>();
        if (this->tilingData_->ifMask) {
            int64_t batchIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
            int64_t seqIdx = this->tilingData_->baseS * this->baseSIdx + sIdx;
            int64_t tokenIdx = batchIdx * this->tilingData_->sSize + seqIdx;
            bool maskValue = this->maskGm(tokenIdx);
            SetWaitFlag<HardEvent::S_V>(HardEvent::S_V);
            if (maskValue) {
                Mul(y2Fp32, xLocalFp32, localW2FP32, this->alignBaseH);
                PipeBarrier<PIPE_V>();
                Add(y2Fp32, y2Fp32, y1Fp32, this->alignBaseH);
                PipeBarrier<PIPE_V>();
            } else {
                Duplicate(y2Fp32, static_cast<float>(0.0f), this->alignBaseH);
                PipeBarrier<PIPE_V>();
            }
        } else {
            Mul(y2Fp32, xLocalFp32, localW2FP32, this->alignBaseH);
            PipeBarrier<PIPE_V>();
            Add(y2Fp32, y2Fp32, y1Fp32, this->alignBaseH);
            PipeBarrier<PIPE_V>();
        }
        // Update y1, y0
        Mul(y1Fp32, xLocalFp32, localW1FP32, this->alignBaseH);
        PipeBarrier<PIPE_V>();
        Add(y1Fp32, y1Fp32, y0Fp32, this->alignBaseH);
        PipeBarrier<PIPE_V>();
        Mul(y0Fp32, xLocalFp32, localW0FP32, this->alignBaseH);
        PipeBarrier<PIPE_V>();
    }

    template <typename T>
    __aicore__ inline void CopyOut(
        const LocalTensor<float> &y2Fp32, const GlobalTensor<T> &dstNd, int64_t bIdx, int64_t sIdx)
    {
        LocalTensor<T> outLocal = this->outQueue.template AllocTensor<T>();
        if constexpr (std::is_same<T, bfloat16_t>::value) {
            Cast(outLocal, y2Fp32, RoundMode::CAST_RINT, this->alignBaseH);
        } else if constexpr (std::is_same<T, half>::value) {
            Cast(outLocal, y2Fp32, RoundMode::CAST_NONE, this->alignBaseH);
        }
        this->outQueue.EnQue(outLocal);
        outLocal = this->outQueue.template DeQue<T>();
        // Copyout output [S, B, H]
        int64_t seqIdx = this->tilingData_->baseS * this->baseSIdx + sIdx;
        int64_t batchIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
        int64_t gmOffset = seqIdx * this->tilingData_->bSize * this->tilingData_->hSize +
                           batchIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
        DataCopyExtParams copyParamsContinguous;
        copyParamsContinguous.blockCount = NUM_ONE;
        copyParamsContinguous.blockLen = this->baseH * sizeof(T);
        copyParamsContinguous.srcStride = 0;
        copyParamsContinguous.dstStride = 0;
        DataCopyPad(dstNd[gmOffset], outLocal, copyParamsContinguous);
        this->outQueue.FreeTensor(outLocal);
    }

private:
};
}  // namespace AiInfraAggregateHidden

#endif  // _AGGREGATE_HIDDEN_H_

