/*!
 * \file ai_infra_aggregate_hidden_common.h
 * \brief
 */
#ifndef _AGGREGATE_HIDDEN_COMMON_H_
#define _AGGREGATE_HIDDEN_COMMON_H_
#include "kernel_operator.h"
#include "kernel_tiling/kernel_tiling.h"
#include "kernel_utils.h"

namespace AiInfraAggregateHidden {
using namespace AscendC;

constexpr int64_t NUM_ZERO = 0;
constexpr int64_t NUM_ONE = 1;
constexpr int64_t NUM_TWO = 2;
constexpr int64_t NUM_THREE = 3;
constexpr int64_t BLOCK_SIZE = 32;
constexpr int64_t ALIGN_SIZE = 16;  // f16/bf16 对齐到32字节

template <HardEvent event>
__aicore__ inline void SetWaitFlag(HardEvent evt)
{
    event_t eventId = static_cast<event_t>(GetTPipePtr()->FetchEventID(evt));
    SetFlag<event>(eventId);
    WaitFlag<event>(eventId);
}

template <typename DTYPE>
class KernelAiInfraAggregateHiddenCutHBS {
public:
    __aicore__ inline KernelAiInfraAggregateHiddenCutHBS(TPipe *pipe, const AiInfraAggregateHiddenTilingData *tiling)
        : pipe_(pipe), tilingData_(tiling)
    {}

    __aicore__ inline int64_t AlignData(int64_t a)
    {
        return (a + ALIGN_SIZE - NUM_ONE) / ALIGN_SIZE * ALIGN_SIZE;
    }

    __aicore__ inline void InitSharedData()
    {
        this->baseH = this->tilingData_->baseH;
        this->baseB = this->tilingData_->baseB;
        this->baseS = this->tilingData_->baseS;
        this->baseHIdx = GetBlockIdx() % this->tilingData_->baseHCnt;
        this->baseBIdx = (GetBlockIdx() / this->tilingData_->baseHCnt) % this->tilingData_->baseBCnt;
        this->baseSIdx =
            (GetBlockIdx() / (this->tilingData_->baseHCnt * this->tilingData_->baseBCnt)) % this->tilingData_->baseSCnt;

        // 32字节对齐
        this->alignBaseH = AlignData(this->baseH);
        this->alignBaseHTail = AlignData(this->tilingData_->baseHTail);

        // 处理尾块
        if (this->baseHIdx == this->tilingData_->baseHCnt - NUM_ONE) {
            this->baseH = this->tilingData_->baseHTail;
            this->alignBaseH = this->alignBaseHTail;
        }
        if (this->baseSIdx == this->tilingData_->baseSCnt - NUM_ONE) {
            this->baseS = this->tilingData_->baseSTail;
        }
        if (this->baseBIdx == this->tilingData_->baseBCnt - NUM_ONE) {
            this->baseB = this->tilingData_->baseBTail;
        }
    }

protected:
    // Shared Constants to be removed
    int64_t baseH{0};
    int64_t baseB{0};
    int64_t baseS{0};
    int64_t baseHIdx{0};
    int64_t baseBIdx{0};
    int64_t baseSIdx{0};
    int64_t alignBaseH{0};
    int64_t alignBaseHTail{0};

    // Sahred members
    TPipe *pipe_ = nullptr;
    const AiInfraAggregateHiddenTilingData *tilingData_;

    GlobalTensor<DTYPE> inputGm, weightGm, outputGm;
    GlobalTensor<bool> maskGm;

    TQue<QuePosition::VECIN, 1> inQueueX;   // baseH
    TQue<QuePosition::VECIN, 1> inQueueW;   // 3 * baseH
    TQue<QuePosition::VECOUT, 1> outQueue;  // baseH
    TBuf<TPosition::VECCALC> y0;
    TBuf<TPosition::VECCALC> y1;
    TBuf<TPosition::VECCALC> y2;
    TBuf<TPosition::VECCALC> inputFp32;  // baseH
};

}  // namespace AiInfraAggregateHidden

#endif  // _AGGREGATE_HIDDEN_COMMON_H_

